BEGIN;
CREATE TABLE IF NOT EXISTS perfiles_usuario (usuario_id TEXT PRIMARY KEY REFERENCES usuarios(id), telefono TEXT NOT NULL DEFAULT '', documento TEXT NOT NULL DEFAULT '', direccion TEXT NOT NULL DEFAULT '', fecha_actualizacion TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS calendario_tarifas (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, alojamiento_id INTEGER NOT NULL REFERENCES alojamientos(id), fecha TEXT NOT NULL, precio NUMERIC(12,2) CHECK (precio > 0), cupo INTEGER CHECK (cupo >= 0), cerrado BOOLEAN NOT NULL DEFAULT FALSE, nota TEXT NOT NULL DEFAULT '', actor_id TEXT NOT NULL REFERENCES usuarios(id), fecha_actualizacion TEXT NOT NULL, UNIQUE(alojamiento_id,fecha));
CREATE TABLE IF NOT EXISTS facturas (id TEXT PRIMARY KEY, reserva_id TEXT NOT NULL UNIQUE REFERENCES reservas(id), usuario_id TEXT NOT NULL REFERENCES usuarios(id), numero TEXT NOT NULL UNIQUE, emisor TEXT NOT NULL, cliente TEXT NOT NULL, fecha_emision TEXT NOT NULL, subtotal NUMERIC(12,2) NOT NULL CHECK (subtotal >= 0), impuestos NUMERIC(12,2) NOT NULL DEFAULT 0, total NUMERIC(12,2) NOT NULL CHECK (total >= 0), moneda TEXT NOT NULL DEFAULT 'USD', estado TEXT NOT NULL CHECK (estado IN ('EMITIDA','ANULADA')), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS detalles_factura (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, factura_id TEXT NOT NULL REFERENCES facturas(id), descripcion TEXT NOT NULL, cantidad INTEGER NOT NULL CHECK (cantidad > 0), precio_unitario NUMERIC(12,2) NOT NULL CHECK (precio_unitario > 0), subtotal NUMERIC(12,2) NOT NULL CHECK (subtotal > 0));
CREATE TABLE IF NOT EXISTS resenas_estancia (id TEXT PRIMARY KEY, reserva_id TEXT NOT NULL UNIQUE REFERENCES reservas(id), usuario_id TEXT NOT NULL REFERENCES usuarios(id), alojamiento_id INTEGER NOT NULL REFERENCES alojamientos(id), puntuacion INTEGER NOT NULL CHECK (puntuacion BETWEEN 1 AND 10), comentario TEXT NOT NULL, fecha_creacion TEXT NOT NULL, respuesta TEXT NOT NULL DEFAULT '', respondido_por TEXT REFERENCES usuarios(id), fecha_respuesta TEXT);
CREATE INDEX IF NOT EXISTS calendario_fecha ON calendario_tarifas(fecha);
CREATE INDEX IF NOT EXISTS resenas_estancia_alojamiento ON resenas_estancia(alojamiento_id);
ALTER TABLE perfiles_usuario ENABLE ROW LEVEL SECURITY;
ALTER TABLE calendario_tarifas ENABLE ROW LEVEL SECURITY;
ALTER TABLE facturas ENABLE ROW LEVEL SECURITY;
ALTER TABLE detalles_factura ENABLE ROW LEVEL SECURITY;
ALTER TABLE resenas_estancia ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON perfiles_usuario,calendario_tarifas,facturas,detalles_factura,resenas_estancia FROM anon,authenticated;
COMMIT;
